import unittest
from candidate import sort_third

class TestSortThird(unittest.TestCase):
    def test_sort_third_empty_list(self):
        self.assertEqual(sort_third([]), [])

    def test_sort_third_single_element(self):
        self.assertEqual(sort_third([3]), [3])

    def test_sort_third_single_element_divisible_by_three(self):
        self.assertEqual(sort_third([3]), [3])

    def test_sort_third_normal_case(self):
        self.assertEqual(sort_third([1, 2, 3]), [1, 2, 3])

    def test_sort_third_divisible_by_three(self):
        self.assertEqual(sort_third([5, 6, 3, 4, 8, 9, 2]), [2, 6, 3, 4, 8, 9, 5])

    def test_sort_third_all_elements_divisible_by_three(self):
        self.assertEqual(sort_third([3, 6, 9]), [3, 6, 9])

    def test_sort_third_negative_numbers(self):
        self.assertEqual(sort_third([-5, -6, -3, -4, -8, -9, -2]), [-2, -6, -3, -4, -8, -9, -5])

    def test_sort_third_mixed_numbers(self):
        self.assertEqual(sort_third([5, 6, -3, 4, 8, 9, 2]), [-3, 6, [2, 5, 4, 8, 9])

    def test_sort_third_float_numbers(self):
        self.assertListEqual(sort_third([3.14, 2.72, 1.618, 4.14, 1.0]), [1.0, 1.618, 2.72, 3.14, 4.14])

    def test_sort_third_list_of_lists(self):
        self.assertEqual(sort_third([[1, 2], [3, 4], [5, 6], [3, 8]]), [[1, 2], [3, 4], [3, 8], [5, 6]])

